insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('attachments','attachments',false,10485760,array['image/png','image/jpeg','application/pdf','text/plain','text/markdown']) on conflict(id) do nothing;
create policy attachment_owner_read on storage.objects for select to authenticated using(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text);
create policy attachment_owner_insert on storage.objects for insert to authenticated with check(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.attachments a where a.storage_key=name and a.owner_id=auth.uid()));
create policy attachment_owner_update on storage.objects for update to authenticated using(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text);
create policy attachment_owner_delete on storage.objects for delete to authenticated using(bucket_id='attachments' and (storage.foldername(name))[1]=auth.uid()::text);
